// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // owner is address(this) (deployer); accept the ETH that withdrawAll transfers back
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18); // nonzero deposit; keep it admissible/wide
        // deposit `amount` into c via its payable fallback, funded by the owner (this test contract)
        vm.deal(address(this), amount);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk, "deposit via fallback failed");
        // owner (this contract) drives withdrawAll; reference transfers the full balance out
        try c.withdrawAll() {
            assertTrue(address(c).balance == 0, "withdrawAll must drain the contract balance");
        } catch {
            assertTrue(false, "withdrawAll by owner must succeed for a funded owner");
        }
    }
}
